sha256:73f864dfd015fc18fe89bb89da3f09be3.content:
/**
 * SPDX-License-Identifier: MIT
 **/

pragma solidity ^0.8.20;

import {AppStorage} from "contracts/beanstalk/storage/AppStorage.sol";
import {LibDiamond} from "contracts/libraries/LibDiamond.sol";
import {LibRedundantMath256} from "contracts/libraries/Math/LibRedundantMath256.sol";

/**
 * @title Pause Facet handles the pausing/unpausing of Beanstalk.
 **/
contract PauseFacet {
    AppStorage internal s;

    using LibRedundantMath256 for uint256;

    event Pause(uint256 timestamp);
    event Unpause(uint256 timestamp, uint256 timePassed);

    /**
     * Pause / Unpause
     **/

    function pause() external payable {
        LibDiamond.enforceIsOwnerOrContract();
        require(!s.sys.paused, "Pause: already paused.");
        s.sys.paused = true;
        s.sys.pausedAt = uint128(block.timestamp);
        emit Pause(block.timestamp);
    }

    function unpause() external payable {
        LibDiamond.enforceIsOwnerOrContract();
        require(s.sys.paused, "Pause: not paused.");
        s.sys.paused = false;
        uint256 timePassed = block.timestamp.sub(uint256(s.sys.pausedAt));
        timePassed = (timePassed.div(3600).add(1)).mul(3600);
        s.sys.season.start = s.sys.season.start.add(timePassed);
        emit Unpause(block.timestamp, timePassed);
    }
}

sha256:7410a60efd885a9e9b7bbcc994c8323cd.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/// @title For calculating a percentage of an amount, using bips
library BipsLibrary {
    uint256 internal constant BPS_DENOMINATOR = 10_000;

    /// @notice emitted when an invalid percentage is provided
    error InvalidBips();

    /// @param amount The total amount to calculate a percentage of
    /// @param bips The percentage to calculate, in bips
    function calculatePortion(uint256 amount, uint256 bips) internal pure returns (uint256) {
        if (bips > BPS_DENOMINATOR) revert InvalidBips();
        return (amount * bips) / BPS_DENOMINATOR;
    }
}

